/* Modern Clean Refined B2B Stat Cards & Quick Actions */
.stat-card-modern-dark { background-color: #121415; color: #ffffff; border: 1px solid rgba(255,255,255,0.08); border-radius: 16px; padding: 24px; transition: transform 0.2s ease, box-shadow 0.2s ease; shadow: 0 4px 20px rgba(0,0,0,0.15); }
.stat-card-modern-light { background-color: #ffffff; color: #121415; border: 1px solid rgba(0,0,0,0.06); border-radius: 16px; padding: 24px; transition: transform 0.2s ease, box-shadow 0.2s ease; shadow: 0 2px 12px rgba(0,0,0,0.03); }
.quick-action-card { background: #ffffff; border: 1px solid rgba(0,0,0,0.06); border-radius: 14px; padding: 20px; transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1); cursor: pointer; }
.quick-action-card:hover { border-color: rgba(0, 212, 161, 0.4); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0, 212, 161, 0.08); }
.quick-action-icon-box { width: 42px; height: 42px; border-radius: 10px; background: rgba(0, 212, 161, 0.08); color: #00b88c; display: flex; align-items: center; justify-content: center; }
